import type { VerticalTabBarProps } from "./vertical-tab-bar.types";

import React, { forwardRef } from "react";
import * as RadixTabs from "@radix-ui/react-tabs";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { useUniqueId } from "@system";

import { TabBarContext } from "../tab-bar/hooks/use-tab-bar";
import { useTabBarManager } from "../tab-bar/hooks/use-tab-bar-manager";

import { VerticalTabBarClasses, StyledVerticalTabBar } from "./vertical-tab-bar.styles";
import {
  VerticalTabBarHeader,
  VerticalTabBarList,
  VerticalTabBarMain,
  VerticalTabBarPanel,
  VerticalTabBarSection,
  VerticalTabBarTitle,
} from "./subcomponents";

type VerticalTabBarComponent = React.ForwardRefExoticComponent<
  VerticalTabBarProps & React.RefAttributes<HTMLDivElement>
> & {
  Header: typeof VerticalTabBarHeader;
  List: typeof VerticalTabBarList;
  Main: typeof VerticalTabBarMain;
  Panel: typeof VerticalTabBarPanel;
  Section: typeof VerticalTabBarSection;
  Title: typeof VerticalTabBarTitle;
};

const VerticalTabBar = forwardRef<HTMLDivElement, VerticalTabBarProps & RadixTabs.TabsProps>(
  (
    {
      className,
      variant = "default",
      children,
      defaultValue,
      rememberActiveTab = false,
      uniqueId,
      onValueChange,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(VerticalTabBarClasses.root, className);
    const addTabId = useUniqueId("add-tab");
    const { activeTab, setActiveTab } = useTabBarManager(
      defaultValue,
      rememberActiveTab,
      uniqueId,
      onValueChange,
      addTabId,
    );

    return (
      <TabBarContext.Provider
        value={{ activeTab, setActiveTab, variant, addTabId, orientation: "vertical" }}
      >
        <StyledVerticalTabBar
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          defaultValue={defaultValue}
          orientation="vertical"
          value={activeTab}
          variant={variant}
          onValueChange={setActiveTab}
          {...props}
        >
          {children}
        </StyledVerticalTabBar>
      </TabBarContext.Provider>
    );
  },
) as VerticalTabBarComponent;

VerticalTabBar.displayName = "VerticalTabBar";

VerticalTabBar.Header = VerticalTabBarHeader;
VerticalTabBar.List = VerticalTabBarList;
VerticalTabBar.Main = VerticalTabBarMain;
VerticalTabBar.Panel = VerticalTabBarPanel;
VerticalTabBar.Section = VerticalTabBarSection;
VerticalTabBar.Title = VerticalTabBarTitle;

export default VerticalTabBar;
